using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using OneWay.Battle3D;
public static class TestNewPlayerLocomotion{
 static void Check(bool b,string message){if(!b)throw new Exception(message);}
 public static object Run(){Check(Application.isPlaying,"Requires Play Mode");var combo=UnityEngine.Object.FindFirstObjectByType<NewPlayerAttackCombo>();var p=combo.GetComponent<BattlePlayerController>();var move=p.GetComponent<NewPlayerLocomotion>();var health=p.GetComponent<BattlePlayerHealth>();var body=p.GetComponent<BattleArenaBody>();var motor=p.GetComponent<CharacterController>();var pos=p.transform.position;var rot=p.transform.rotation;bool enabled=p.enabled,bodyEnabled=body.enabled;var ground=GameObject.CreatePrimitive(PrimitiveType.Cube);ground.transform.position=new Vector3(1000,-.5f,1000);ground.transform.localScale=new Vector3(100,1,100);p.enabled=false;body.enabled=false;motor.enabled=false;p.transform.position=new Vector3(1000,.01f,1000);motor.enabled=true;Physics.SyncTransforms();combo.readMouseInput=false;health.ResetHealth();var errors=new List<string>();Application.LogCallback log=(m,s,t)=>{if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m);};Application.logMessageReceived+=log;
 try{
  p.ProcessControlFrame(0,true,false,0);Check(combo.IsActive,"Attack did not start");p.ProcessControlFrame(0,true,false,0);Check(combo.Queued,"Queue missing");p.ProcessControlFrame(0,false,true,0);Check(p.IsDashing&&!combo.IsActive&&!combo.Queued,"Roll did not interrupt combo");float hp=health.Health;health.TakeDamage(20);Check(health.Health==hp,"Roll invulnerability missing");var start=p.transform.position;float duration=move.rollClip.length/p.rollAnimationSpeed;combo.Tick(duration);float rollDistance=Vector3.ProjectOnPlane(p.transform.position-start,Vector3.up).magnitude;Check(Mathf.Abs(rollDistance-p.rollDistance)<.02f,"Roll distance incorrect "+rollDistance);Check(!p.IsDashing&&p.IsMoving&&move.Running,"Run did not start after roll");start=p.transform.position;combo.Tick(.5f);float runDistance=Vector3.ProjectOnPlane(p.transform.position-start,Vector3.up).magnitude;Check(Mathf.Abs(runDistance-p.moveSpeed*.5f)<.02f,"Run distance incorrect");p.animator.Update(.2f);Check(p.animator.GetCurrentAnimatorStateInfo(0).IsName(move.runClip.name),"Run animation missing");
  p.ProcessControlFrame(0,true,false,0);Check(combo.IsActive&&!p.IsMoving,"Attack did not stop run");p.ProcessControlFrame(-1,false,false,0);Check(p.IsDefenseMode&&p.shield.activeSelf&&!combo.IsActive,"Defense mode did not show shield / cancel attack");p.ProcessControlFrame(0,true,false,0);Check(p.IsBlocking&&move.Parrying,"Parry not active");health.TakeDamage(20);Check(health.Health==hp,"Parry protection missing");bool parried=p.GetComponent<BattleParryEffect>().TryParry(20);Check(parried,"Parry effect did not activate");combo.Tick(move.parryClip.length/p.shieldAnimationSpeed+.01f);Check(!p.IsBlocking&&p.IsDefenseMode&&p.shield.activeSelf,"Parry failed to end");p.ProcessControlFrame(1,true,false,0);Check(!p.IsDefenseMode&&!p.shield.activeSelf&&combo.IsActive,"Attack mode switch failed");p.CancelInput();Check(!combo.IsActive&&!move.Running&&!move.Rolling&&!move.Parrying,"Cancel leaves stale motion");
  p.ProcessControlFrame(-1,true,false,0);p.ProcessControlFrame(0,false,true,0);Check(p.IsDashing&&!p.IsBlocking,"Roll could not interrupt parry");p.CancelInput();p.ProcessControlFrame(1,false,false,0);health.TakeDamage(20);Check(health.Health==hp-20,"Damage remained disabled after roll/parry");Check(errors.Count==0,string.Join("|",errors));return new{passed=true,rollDistance,runDistance,parryEffects=parried,rollAndParryInvulnerability=true,attackInterruptions=true,shieldScale=p.shield.transform.localScale.ToString(),errors};
 }finally{Application.logMessageReceived-=log;p.CancelInput();move.SetDefenseMode(false);motor.enabled=false;p.transform.SetPositionAndRotation(pos,rot);motor.enabled=true;body.enabled=bodyEnabled;p.enabled=enabled;health.ResetHealth();combo.readMouseInput=true;UnityEngine.Object.DestroyImmediate(ground);}}
}
